/** Fields that the MCP editor can author; server identity is the enclosing map key. */
export interface McpSettingsPatchInput {
  transport?: "stdio" | "streamable-http" | "sse";
  command?: string;
  args?: string[];
  url?: string;
  env?: Record<string, string>;
  envVars?: string[];
